import org.junit.jupiter.api.Test;

/**
 * @author Arjohn Kampman
 */
public class BinaryRDFWriterTest extends RDFWriterTest {

	public BinaryRDFWriterTest() {
		super(new BinaryRDFWriterFactory(), new BinaryRDFParserFactory());
	}

	@Test
	void defaultBinaryTransportPreservesExactIdsInsideNestedTripleTerms() throws Exception {
		ValueFactory vf = SimpleValueFactory.getInstance();
		TripleTerm inner = vf.createTripleTerm(vf.createBNode("_:space >\\雪"), vf.createIRI("urn:p"),
				vf.createBNode(""));
		TripleTerm outer = vf.createTripleTerm(vf.createBNode("outer"), vf.createIRI("urn:p"), inner);
		Statement statement = vf.createStatement(vf.createIRI("urn:subject"), vf.createIRI("urn:p"), outer,
				vf.createBNode("context"));
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		Rio.write(List.of(statement), output, RDFFormat.BINARY);
		List<Statement> received = new ArrayList<>();
		BinaryRDFParser parser = new BinaryRDFParser();
		parser.getParserConfig().set(BasicParserSettings.PRESERVE_BNODE_IDS, true);
		parser.setRDFHandler(new StatementCollector(received));
		parser.parse(new ByteArrayInputStream(output.toByteArray()), "urn:base:");
		assertEquals(List.of(statement), received);
	}

	@Test
	void nativeTripleTermsPreserveIdsNestingLiteralTypesAndAliasSeparationInBothVersions() throws Exception {
		ValueFactory vf = SimpleValueFactory.getInstance();
		for (long version : List.of(1L, 2L)) {
			for (String id : List.of("", "_:prefix", "space >\\雪", "literal%20+", "\\u0041", "emoji😀", "node.")) {
				BNode exact = vf.createBNode(id);
				BNode formerAlias = vf.createBNode(NTriplesUtil.toNTriplesString(exact).substring(2));
				Value nested = vf.createLiteral("literal <_:id> >> \" \\ \n", "ar", Literal.BaseDirection.RTL);
				for (int depth = 0; depth < 64; depth++) {
					nested = vf.createTripleTerm(exact, vf.createIRI("urn:p"), nested);
				}
				List<Statement> statements = List.of(
						vf.createStatement(exact, vf.createIRI("urn:nested"), nested, exact),
						vf.createStatement(vf.createIRI("urn:typed"), vf.createIRI("urn:p"),
								vf.createTripleTerm(exact, vf.createIRI("urn:p"),
										vf.createLiteral("typed", vf.createIRI("urn:datatype")))),
						vf.createStatement(formerAlias, vf.createIRI("urn:alias"),
								vf.createTripleTerm(formerAlias, vf.createIRI("urn:p"), formerAlias)));
				assertEquals(statements, roundTrip(statements, version), "Binary version " + version + ", ID " + id);
			}
		}
	}

	@Test
	void nativeCapableBinaryParserStillReadsLegacyEncodedTripleIris() throws Exception {
		ValueFactory vf = SimpleValueFactory.getInstance();
		TripleTerm legacy = vf.createTripleTerm(vf.createBNode("legacy"), vf.createIRI("urn:p"),
				vf.createLiteral("old encoded response"));
		Value encoded = TripleTermUtil.<Value>toRDFEncodedValue(legacy);
		Statement transported = vf.createStatement(vf.createIRI("urn:subject"), vf.createIRI("urn:p"), encoded);
		Statement expected = vf.createStatement(vf.createIRI("urn:subject"), vf.createIRI("urn:p"), legacy);
		for (long version : List.of(1L, 2L)) {
			assertEquals(List.of(expected), roundTrip(List.of(transported), version));
		}
	}

	private List<Statement> roundTrip(List<Statement> statements, long version) throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryRDFWriter writer = new BinaryRDFWriter(output);
		writer.set(BinaryRDFWriterSettings.VERSION, version);
		writer.startRDF();
		statements.forEach(writer::handleStatement);
		writer.endRDF();
		List<Statement> received = new ArrayList<>();
		BinaryRDFParser parser = new BinaryRDFParser();
		parser.getParserConfig().set(BasicParserSettings.PRESERVE_BNODE_IDS, true);
		parser.setRDFHandler(new StatementCollector(received));
		parser.parse(new ByteArrayInputStream(output.toByteArray()), "urn:base:");
		return received;
	}

	@Override
	protected RioSetting<?>[] getExpectedSupportedSettings() {
		return new RioSetting[] {
				BasicWriterSettings.RDF_OUTPUT_VERSION,
				BinaryRDFWriterSettings.VERSION,
				BinaryRDFWriterSettings.BUFFER_SIZE,
				BinaryRDFWriterSettings.CHARSET,
				BinaryRDFWriterSettings.RECYCLE_IDS
		};
	}
}
